module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg reset;
    wire shift_ena;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .shift_ena(shift_ena)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;

        // Apply reset for a couple of cycles
        @(posedge clk);
        #1;

        // Check cycle 1 of reset (shift_ena should be 1)
        if (shift_ena !== 1'b1) begin
            errors = errors + 1;
        end

        // Release reset
        @(posedge clk);
        reset = 0;
        #1;

        // According to the RTL, upon reset, shift_ena is asserted for 4 cycles total.
        // Let's trace cycle by cycle:
        // Reset cycle: count=0, shift_ena=1
        // After reset is deasserted:
        // Cycle 1 (posedge after reset deasserted): count was 0, count < 3 so count becomes 1, shift_ena = 1
        // Cycle 2: count was 1, count < 3 so count becomes 2, shift_ena = 1
        // Cycle 3: count was 2, count < 3 so count becomes 3, shift_ena = 1
        // Cycle 4: count was 3, count not < 3 so shift_ena = 0

        // Let's check the sequence of shift_ena for the next 6 cycles
        // Expected shift_ena sequence after reset=1:
        // Reset state: 1
        // Post-reset cycle 1: 1
        // Post-reset cycle 2: 1
        // Post-reset cycle 3: 1
        // Post-reset cycle 4 onwards: 0

        // We already checked reset cycle shift_ena == 1.

        // Check post-reset cycle 1
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b1) errors = errors + 1;

        // Check post-reset cycle 2
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b1) errors = errors + 1;

        // Check post-reset cycle 3
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b1) errors = errors + 1;

        // Check post-reset cycle 4 (should be 0)
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b0) errors = errors + 1;

        // Check subsequent cycles to ensure it stays 0 forever until reset
        for (i = 0; i < 5; i = i + 1) begin
            @(posedge clk);
            #1;
            if (shift_ena !== 1'b0) errors = errors + 1;
        end

        // Test re-applying reset
        reset = 1;
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b1) errors = errors + 1;

        reset = 0;
        @(posedge clk);
        #1;
        if (shift_ena !== 1'b1) errors = errors + 1;

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
